def set_zeroes(matrix):
    zero_rows = set()
    zero_cols = set()
    for r, row in enumerate(matrix):              # pass 1: only look, and note where the zeros are
        for c, value in enumerate(row):
            if value == 0:
                zero_rows.add(r)
                zero_cols.add(c)
    for r, row in enumerate(matrix):              # pass 2: only write, judging each cell by the notes
        for c in range(len(row)):
            if r in zero_rows or c in zero_cols:
                row[c] = 0
